import React from "react";
import Car from "./../components/Car";

function App() {
  const carInfo = { name: "Ford", model: "Mustang" };

  return (
    <div>
      <h1>Welcome to my React Garage</h1>
      <Car carInfo={carInfo} />
    </div>
  );
}

export default App;
